#!/usr/bin/env python3
"""Add an opt-in animated Telega identity badge next to the account's own profile name."""
from pathlib import Path
import sys

root = Path("TMessagesProj/src/main/java/org/telegram")
feature_patch = Path(".github/patches/telega_features.py")
profile = root / "ui" / "ProfileActivity.java"
settings_patch = feature_patch.read_text(encoding="utf-8")
profile_java = profile.read_text(encoding="utf-8")

# Add preference accessors to the TelegaFeatures helper generated by telega_features.py.
old = '''    public static boolean isAntiSoundEnabled() {
        return prefs().getBoolean("anti_sound", false);
    }
    public static void setAntiSoundEnabled(boolean enabled) {
        prefs().edit().putBoolean("anti_sound", enabled).apply();
        if (enabled) markExistingDialogsHandled(UserConfig.selectedAccount);
    }'''
new = old + '''

    public static boolean isBadgeEnabled() {
        return prefs().getBoolean("telega_badge", false);
    }
    public static void setBadgeEnabled(boolean enabled) {
        prefs().edit().putBoolean("telega_badge", enabled).apply();
        AndroidUtilities.runOnUIThread(() -> {
            try {
                NotificationCenter.getGlobalInstance().postNotificationName(NotificationCenter.updateInterfaces, MessagesController.UPDATE_MASK_ALL);
            } catch (Throwable ignored) {}
        });
    }'''
if "public static boolean isBadgeEnabled()" not in settings_patch:
    if old not in settings_patch:
        print("ERROR: TelegaFeatures badge preference insertion anchor missing", file=sys.stderr)
        sys.exit(1)
    settings_patch = settings_patch.replace(old, new, 1)
    feature_patch.write_text(settings_patch, encoding="utf-8")

# The feature generator ran earlier in this build, so patch the already-generated Java helper too.
feature_java = root / "messenger" / "TelegaFeatures.java"
helper_source = feature_java.read_text(encoding="utf-8")
if "public static boolean isBadgeEnabled()" not in helper_source:
    helper_anchor = old
    helper_new = new[len(old):] if new.startswith(old) else ""
    if helper_anchor not in helper_source:
        print("ERROR: generated TelegaFeatures helper insertion anchor missing", file=sys.stderr)
        sys.exit(1)
    helper_source = helper_source.replace(helper_anchor, helper_anchor + helper_new, 1)
    feature_java.write_text(helper_source, encoding="utf-8")

# Add the switch to TelegaSettingsActivity's generated source.
settings = root / "ui" / "TelegaSettingsActivity.java"
s = settings.read_text(encoding="utf-8")
row_anchor = "        fragmentView = scroll;"
badge_row = '''        addToggle(context, list, "Значок Telega",
                "Пульсирующий значок рядом с твоим именем в собственном профиле.",
                TelegaFeatures.isBadgeEnabled(),
                (button, enabled) -> TelegaFeatures.setBadgeEnabled(enabled));

'''
if "TelegaFeatures.isBadgeEnabled()" not in s:
    if row_anchor not in s:
        print("ERROR: badge toggle insertion anchor missing", file=sys.stderr)
        sys.exit(1)
    s = s.replace(row_anchor, badge_row + row_anchor, 1)
    settings.write_text(s, encoding="utf-8")

drawable = root / "ui" / "Components" / "TelegaBadgeDrawable.java"
drawable.write_text(r'''package org.telegram.ui.Components;

import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.Rect;
import android.graphics.drawable.Drawable;
import android.os.SystemClock;

import org.telegram.messenger.AndroidUtilities;

/** Small animated Telega paper-plane badge. No external assets or network resources. */
public final class TelegaBadgeDrawable extends Drawable {
    private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Path plane = new Path();
    private final Runnable frame = this::invalidateSelf;
    private final long startedAt = SystemClock.uptimeMillis();

    @Override
    public void draw(Canvas canvas) {
        Rect bounds = getBounds();
        if (bounds.width() <= 0 || bounds.height() <= 0) return;
        float cx = bounds.exactCenterX();
        float cy = bounds.exactCenterY();
        float unit = Math.min(bounds.width(), bounds.height()) / 20.0f;
        float phase = (SystemClock.uptimeMillis() - startedAt) % 1200L / 1200.0f;

        canvas.save();
        canvas.translate(cx, cy);
        float ringRadius = (6.6f + phase * 3.0f) * unit;
        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(1.2f * unit);
        paint.setColor(Color.argb((int) (105 * (1.0f - phase)), 35, 151, 245));
        canvas.drawCircle(0, 0, ringRadius, paint);

        paint.setStyle(Paint.Style.FILL);
        paint.setColor(Color.rgb(35, 151, 245));
        canvas.drawCircle(0, 0, 6.5f * unit, paint);

        plane.reset();
        plane.moveTo(-4.2f * unit, -0.1f * unit);
        plane.lineTo(4.1f * unit, -3.2f * unit);
        plane.lineTo(1.9f * unit, 3.4f * unit);
        plane.lineTo(0.3f * unit, 1.2f * unit);
        plane.lineTo(-1.7f * unit, 2.6f * unit);
        plane.lineTo(-1.2f * unit, 0.6f * unit);
        plane.close();
        paint.setColor(Color.WHITE);
        canvas.drawPath(plane, paint);
        canvas.restore();

        scheduleSelf(frame, SystemClock.uptimeMillis() + 40);
    }

    @Override public void setAlpha(int alpha) {}
    @Override public void setColorFilter(android.graphics.ColorFilter filter) {}
    @Override public int getOpacity() { return android.graphics.PixelFormat.TRANSLUCENT; }
    @Override public int getIntrinsicWidth() { return AndroidUtilities.dp(20); }
    @Override public int getIntrinsicHeight() { return AndroidUtilities.dp(20); }
}
''', encoding="utf-8")

# Display only on the currently signed-in user's own profile, and remove it when the switch is off.
anchor = "        if (avatarContainer == null || nameTextView == null || getParentActivity() == null) {"
if "new org.telegram.ui.Components.TelegaBadgeDrawable()" not in profile_java:
    start = profile_java.find(anchor)
    if start < 0:
        print("ERROR: ProfileActivity badge insertion anchor missing", file=sys.stderr)
        sys.exit(1)
    close = profile_java.find("\n        }", start)
    if close < 0:
        print("ERROR: ProfileActivity guard end not found", file=sys.stderr)
        sys.exit(1)
    close += len("\n        }")
    code = '''

        if (nameTextView != null) {
            boolean telegaOwnProfile = userId == UserConfig.getInstance(currentAccount).getClientUserId();
            android.graphics.drawable.Drawable telegaRight = nameTextView.getCompoundDrawablesRelative()[2];
            if (telegaOwnProfile && org.telegram.messenger.TelegaFeatures.isBadgeEnabled()) {
                if (!(telegaRight instanceof org.telegram.ui.Components.TelegaBadgeDrawable)) {
                    nameTextView.setCompoundDrawablePadding(AndroidUtilities.dp(3));
                    nameTextView.setCompoundDrawablesRelativeWithIntrinsicBounds(
                            nameTextView.getCompoundDrawablesRelative()[0],
                            nameTextView.getCompoundDrawablesRelative()[1],
                            new org.telegram.ui.Components.TelegaBadgeDrawable(),
                            nameTextView.getCompoundDrawablesRelative()[3]);
                }
            } else if (telegaRight instanceof org.telegram.ui.Components.TelegaBadgeDrawable) {
                nameTextView.setCompoundDrawablesRelativeWithIntrinsicBounds(
                        nameTextView.getCompoundDrawablesRelative()[0],
                        nameTextView.getCompoundDrawablesRelative()[1],
                        null,
                        nameTextView.getCompoundDrawablesRelative()[3]);
            }
        }
'''
    profile_java = profile_java[:close] + code + profile_java[close:]
    profile.write_text(profile_java, encoding="utf-8")

print("Telega animated identity badge patch applied.")
